package com.personal.assistant.module.scheduler.job;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.service.BackupService;import org.springframework.stereotype.Component;@Component public class DataBackupHandler implements JobHandler{private final BackupService service;public DataBackupHandler(BackupService s){service=s;}public String type(){return "DATA_BACKUP";}public String execute(String config){BackupRecord r=service.runFullBackup();return "备份完成: "+r.getFilePath();}}